\begin{ex}%[9D2H3-2]
Tính tổng tất cả các giá trị nguyên âm của $x$ thỏa mãn bất phương trình $\dfrac{2x - 3}{7} \le \dfrac{4x + 9}{5}$.
\shortans{-10}
\loigiai{
Nhân cả hai vế của bất phương trình với $35 > 0$ ta được:\\
$5(2x - 3) \le 7(4x + 9) \Leftrightarrow 10x - 15 \le 28x + 63$.\\
Chuyển vế thu gọn: $-18x \le 78 \Leftrightarrow x \ge -\dfrac{13}{3} \approx -4{,}33$.\\
Các nghiệm nguyên âm thỏa mãn là $x \in \{-4; -3; -2; -1\}$, tổng bằng $-10$.
}\end{ex}

\begin{ex}%[9D2H3-2]
Tính tổng tất cả các giá trị nguyên âm của $x$ thỏa mãn bất phương trình $\dfrac{2x - 5}{9} \le \dfrac{3x + 7}{5}$.
\shortans{-15}
\loigiai{
Nhân cả hai vế của bất phương trình với $45 > 0$ ta được:\\
$5(2x - 5) \le 9(3x + 7) \Leftrightarrow 10x - 25 \le 27x + 63$.\\
Chuyển vế thu gọn: $-17x \le 88 \Leftrightarrow x \ge -\dfrac{88}{17} \approx -5{,}18$.\\
Các nghiệm nguyên âm thỏa mãn là $x \in \{-5; -4; -3; -2; -1\}$, tổng bằng $-15$.
}\end{ex}

\begin{ex}%[9D2H3-2]
Tính tổng tất cả các giá trị nguyên âm của $x$ thỏa mãn bất phương trình $\dfrac{3x - 4}{7} \le \dfrac{2x + 5}{3}$.
\shortans{-45}
\loigiai{
Nhân cả hai vế của bất phương trình với $21 > 0$ ta được:\\
$3(3x - 4) \le 7(2x + 5) \Leftrightarrow 9x - 12 \le 14x + 35$.\\
Chuyển vế thu gọn: $-5x \le 47 \Leftrightarrow x \ge -\dfrac{47}{5} \approx -9{,}40$.\\
Các nghiệm nguyên âm thỏa mãn là $x \in \{-9; -8; -7; -6; -5; -4; -3; -2; -1\}$, tổng bằng $-45$.
}\end{ex}
